-- Restrict sensitive read access by role and keep client rows patient-scoped.
DROP POLICY IF EXISTS patient_read ON public."Patient";
CREATE POLICY patient_read ON public."Patient" FOR SELECT TO authenticated USING (public.livya_has_role(ARRAY['SUPERADMIN','ADMIN','CLINICIAN','NUTRITIONIST','THERAPIST','STAFF']) OR "userId"=auth.uid());
DROP POLICY IF EXISTS appointment_read ON public."Appointment";
CREATE POLICY appointment_read ON public."Appointment" FOR SELECT TO authenticated USING (public.livya_has_role(ARRAY['SUPERADMIN','ADMIN','CLINICIAN','STAFF']) OR EXISTS(SELECT 1 FROM public."Patient" p WHERE p.id="Appointment"."patientId" AND p."userId"=auth.uid()));
DROP POLICY IF EXISTS record_read ON public."ClinicalRecord";
CREATE POLICY record_read ON public."ClinicalRecord" FOR SELECT TO authenticated USING (public.livya_has_role(ARRAY['SUPERADMIN','ADMIN','CLINICIAN','NUTRITIONIST']) OR EXISTS(SELECT 1 FROM public."Patient" p WHERE p.id="ClinicalRecord"."patientId" AND p."userId"=auth.uid()));
DROP POLICY IF EXISTS prescription_read ON public."Prescription";
CREATE POLICY prescription_read ON public."Prescription" FOR SELECT TO authenticated USING (public.livya_has_role(ARRAY['SUPERADMIN','ADMIN','CLINICIAN']) OR EXISTS(SELECT 1 FROM public."Patient" p WHERE p.id="Prescription"."patientId" AND p."userId"=auth.uid()));
DROP POLICY IF EXISTS prescription_item_read ON public."PrescriptionItem";
CREATE POLICY prescription_item_read ON public."PrescriptionItem" FOR SELECT TO authenticated USING (public.livya_has_role(ARRAY['SUPERADMIN','ADMIN','CLINICIAN']) OR EXISTS(SELECT 1 FROM public."Prescription" pr JOIN public."Patient" p ON p.id=pr."patientId" WHERE pr.id="PrescriptionItem"."prescriptionId" AND p."userId"=auth.uid()));
DROP POLICY IF EXISTS nutrition_read ON public."NutritionAssessment";
CREATE POLICY nutrition_read ON public."NutritionAssessment" FOR SELECT TO authenticated USING (public.livya_has_role(ARRAY['SUPERADMIN','ADMIN','CLINICIAN','NUTRITIONIST']) OR EXISTS(SELECT 1 FROM public."Patient" p WHERE p.id="NutritionAssessment"."patientId" AND p."userId"=auth.uid()));
DROP POLICY IF EXISTS plans_read ON public."PatientPlan";
CREATE POLICY plans_read ON public."PatientPlan" FOR SELECT TO authenticated USING (public.livya_has_role(ARRAY['SUPERADMIN','ADMIN','CLINICIAN','NUTRITIONIST']) OR EXISTS(SELECT 1 FROM public."Patient" p WHERE p.id="PatientPlan"."patientId" AND p."userId"=auth.uid()));
DROP POLICY IF EXISTS ai_review_read ON public."AIReview";
CREATE POLICY ai_review_read ON public."AIReview" FOR SELECT TO authenticated USING (public.livya_has_role(ARRAY['SUPERADMIN','ADMIN','CLINICIAN']));
DROP POLICY IF EXISTS lab_booking_read ON public."LabBooking";
CREATE POLICY lab_booking_read ON public."LabBooking" FOR SELECT TO authenticated USING (public.livya_has_role(ARRAY['SUPERADMIN','ADMIN','CLINICIAN','STAFF']) OR EXISTS(SELECT 1 FROM public."Patient" p WHERE p.id="LabBooking"."patientId" AND p."userId"=auth.uid()));
DROP POLICY IF EXISTS store_order_read ON public."StoreOrder";
CREATE POLICY store_order_read ON public."StoreOrder" FOR SELECT TO authenticated USING (public.livya_has_role(ARRAY['SUPERADMIN','ADMIN','STAFF']) OR EXISTS(SELECT 1 FROM public."Patient" p WHERE p.id="StoreOrder"."patientId" AND p."userId"=auth.uid()));
DROP POLICY IF EXISTS store_order_item_read ON public."StoreOrderItem";
CREATE POLICY store_order_item_read ON public."StoreOrderItem" FOR SELECT TO authenticated USING (public.livya_has_role(ARRAY['SUPERADMIN','ADMIN','STAFF']) OR EXISTS(SELECT 1 FROM public."StoreOrder" o JOIN public."Patient" p ON p.id=o."patientId" WHERE o.id="StoreOrderItem"."orderId" AND p."userId"=auth.uid()));
